import React from 'react';

function Posts() {
  // Mock data to simulate items fetched from your MongoDB database
  const mockPosts = [
    { id: 1, price: '₹ 15,000', name: 'Yamaha RX100', category: 'Motorcycles', location: 'Kanpur, Uttar Pradesh', date: 'Oct 04' },
    { id: 2, price: '₹ 12,500', name: 'iPhone 11 - 64GB', category: 'Mobile Phones', location: 'Lucknow, Uttar Pradesh', date: 'Oct 02' },
    { id: 3, price: '₹ 800', name: 'Vintage Denim Jacket', category: 'Fashion', location: 'Delhi', date: 'Sep 28' },
    { id: 4, price: '₹ 25,000', name: 'Gaming PC Setup', category: 'Electronics', location: 'Noida, Uttar Pradesh', date: 'Sep 25' },
  ];

  return (
    <div style={{ padding: '20px 40px', backgroundColor: '#f8f9fa' }}>
      <h3 style={{ color: '#002f34', marginBottom: '20px', fontSize: '24px' }}>Fresh Recommendations</h3>
      
      {/* Grid container for the cards */}
      <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
        
        {mockPosts.map(post => (
          <div key={post.id} style={{ 
            width: '260px', 
            border: '1px solid #ccc', 
            borderRadius: '4px', 
            padding: '10px', 
            backgroundColor: 'white',
            cursor: 'pointer',
            display: 'flex',
            flexDirection: 'column'
          }}>
            {/* Image Placeholder */}
            <div style={{ height: '160px', backgroundColor: '#ebeced', marginBottom: '10px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
              <span style={{ color: '#a0a0a0' }}>Product Image</span>
            </div>
            
            {/* Post Details */}
            <h2 style={{ margin: '5px 0', fontSize: '22px', color: '#002f34' }}>{post.price}</h2>
            <p style={{ margin: '0 0 10px 0', color: '#5c6369', fontSize: '15px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {post.name}
            </p>
            
            {/* Location and Date Footer */}
            <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 'auto', color: '#a0a0a0', fontSize: '12px' }}>
              <span>{post.location}</span>
              <span>{post.date}</span>
            </div>
          </div>
        ))}

      </div>
    </div>
  );
}

export default Posts;
